import { test, assert, describe } from 'vitest'
import { alps, artificialStroke, camel, cleanSimulatorDrive, cleanSimulatorRecovery, dromedaryLeft, dromedaryRight, parabola, pyramid, fuzzing } from './BasicCurves.ts'
