    const flankLength = 12
    const movingRegressor = createMovingRegressor(flankLength)
    const curve = createCurveMetrics(0.000000001)
    let i = 0
    while (i <= 488) {
      const yValue = 1000 * Math.PI * i
      const datapoint =  pyramid.solveY(yValue).secondIntegral
      if (!isNaN(datapoint.x)) {
        movingRegressor.push(datapoint.x, datapoint.y)
        curve.push(movingRegressor.secondDerivative(0))
      }
      i++
    }

