describe('Test of the Moving Regressor object after a reset', () => {
  test('Correct movingRegressor behaviour after a reset', () => {
    const flankLength = 4
    const movingRegressor = createMovingRegressor(flankLength)

    movingRegressor.push(0, flywheelPosition(0)) // Datapoint 0
    testFirstDerivative(movingRegressor, undefined)
    testSecondDerivative(movingRegressor, undefined)
    movingRegressor.push(0.234341433963188, flywheelPosition(1)) // Datapoint 1
    testFirstDerivative(movingRegressor, undefined)
    testSecondDerivative(movingRegressor, undefined)
    movingRegressor.push(0.430803114057485, flywheelPosition(2)) // Datapoint 2
    testFirstDerivative(movingRegressor, undefined)
    testSecondDerivative(movingRegressor, undefined)
    movingRegressor.push(0.603370302455080, flywheelPosition(3)) // Datapoint 3
    testFirstDerivative(movingRegressor, 3.999999999999993)
    testSecondDerivative(movingRegressor, 4.000000000000056)

    movingRegressor.reset()

    testFirstDerivative(movingRegressor, undefined)
    testSecondDerivative(movingRegressor, undefined)
    movingRegressor.push(0, flywheelPosition(0)) // Datapoint 0
    testFirstDerivative(movingRegressor, undefined)
    testSecondDerivative(movingRegressor, undefined)
    movingRegressor.push(0.234341433963188, flywheelPosition(1)) // Datapoint 1
    testFirstDerivative(movingRegressor, undefined)
    testSecondDerivative(movingRegressor, undefined)
    movingRegressor.push(0.430803114057485, flywheelPosition(2)) // Datapoint 2
    testFirstDerivative(movingRegressor, undefined)
    testSecondDerivative(movingRegressor, undefined)
    movingRegressor.push(0.603370302455080, flywheelPosition(3)) // Datapoint 3
    testFirstDerivative(movingRegressor, 3.999999999999993)
    testSecondDerivative(movingRegressor, 4.000000000000056)
  })
})

function testFirstDerivative (regressor: Readonly<MovingRegressor>, expectedValue: Readonly<number>) {
  assert.strictEqual(regressor.firstDerivative(0), expectedValue, `First derivative should be ${expectedValue} Radians/sec at ${regressor.X.get(0)} sec, is ${regressor.firstDerivative(0)}`)
}

function testSecondDerivative (regressor: Readonly<MovingRegressor>, expectedValue: Readonly<number>) {
  assert.strictEqual(regressor.secondDerivative(0), expectedValue, `Second derivative should be ${expectedValue} Radians/sec^2 at ${regressor.X.get(0)} sec, is ${regressor.secondDerivative(0)}`)
}

function testCurveLength (curveMetrics: Readonly<CurveAndMetrics>, expectedValue: Readonly<number>) {
  assert.strictEqual(curveMetrics.length, expectedValue, `Expected length should be ${expectedValue}, encountered ${curveMetrics.length}`)
}

function testCurveAverage (curveMetrics: Readonly<CurveAndMetrics>, expectedValue: Readonly<number>) {
  assert.strictEqual(curveMetrics.average, expectedValue, `Expected average should be ${expectedValue}, encountered ${curveMetrics.average}`)
}

function testCurvePeak (curveMetrics: Readonly<CurveAndMetrics>, expectedValue: Readonly<number>) {
  assert.strictEqual(curveMetrics.peak, expectedValue, `Expected peak should be ${expectedValue}, encountered ${curveMetrics.peak}`)
}

function testCurvePeakPosition (curveMetrics: Readonly<CurveAndMetrics>, expectedValue: Readonly<number>) {
  assert.strictEqual(curveMetrics.peakNormalizedPosition, expectedValue, `Expected peakNormalizedPosition should be ${expectedValue}, encountered ${curveMetrics.peakNormalizedPosition}`)
}

function testCurve (curveMetrics: Readonly<CurveAndMetrics>, expectedValue: Readonly<number>) {
  assert.strictEqual(curveMetrics.curve.toString(), expectedValue.toString(), `Expected length should be ${expectedValue}, encountered ${curveMetrics.length}`)
}
